const TODAY=BOOT.clock.today;let NOWT=BOOT.clock.now;
if(!BOOT.clock.demo)setInterval(()=>{NOWT=new Date().toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit',hour12:true}).toLowerCase();},30000);
const fmtPh=p=>String(p).replace(/(\d{5})(\d{5})/,'$1 $2');

// ---------------- sample data (fictional customers, real menu and staff roles)
// ---------------- data from the server
let S=BOOT.state,VER=BOOT.ver,REV=BOOT.rev,SYNCED={},pending=0,syncQ=Promise.resolve(),RETRY=false;
// a save the internet cut off is sent again by the 20 s check below (before any reload), and leaving the page asks first (round 6)
window.addEventListener('beforeunload',e=>{if(pending||RETRY){e.preventDefault();e.returnValue='';}});
const ME=BOOT.me;
const mark=()=>{SYNCED={};for(const k in S)SYNCED[k]=JSON.stringify(S[k]);};mark();
// asks only for the lists that changed since the page's copy (the others stay as they are)
async function reloadState(){try{const r=await fetch('/api/state?have='+encodeURIComponent(JSON.stringify(VER)));if(r.status===401){location.reload();return;}const d=await r.json();if(d.clock.today!==TODAY){location.reload();return;}S=d.partial?{...S,...d.state}:d.state;VER=d.ver;REV=d.rev;LIVE=d.oldLink||null;mark();render();}catch(e){}}
// Sends only the lists that changed since the last save. The server checks the login's
// rights and that nobody else changed the same list meanwhile; if it refuses, the page reloads.
// A change to a list this login may not change (BOOT.can, from the server) is taken back at once, with the reason,
// instead of a "done" message followed by the server's refusal (round 5)
// who may download which CSV (same as EXPORT_ROLES in server/routes.js)
const EXPORT_ROLES={sales:['owner','accountant','manager'],inventory:['owner','accountant','manager','reception'],feedback:['owner','manager','advisor','reception'],calls:['owner','manager','advisor'],transfers:['owner','manager'],claims:['owner','accountant','manager']};
const CAN=new Set(BOOT.can||Object.keys(S));
// Stock kept in the Inventory portal (29 Oct): its address when linked. Then stock lists here are read-only and long lists show
// the first ROWS rows (search for the rest); the stock is changed in the Inventory portal.
const INV_LINK=BOOT.invLink||'',ROWS=300;
// Live link to the old billing sites (29 Oct): bills, job cards, customers, credit, mechanic sales, quotations and coupons
// are read from them within seconds and are read-only here (OLD_LISTS); BOOT.oldLink = {at, ok, err} while it is on.
let LIVE=BOOT.oldLink||null;const OLD_LISTS=['invoices','jobs','customers','credit','mechSales','quotes','coupons','mechList','mechs','partsReq','spareWait','freeSvc','feedback','reminders'];
const oldNote=()=>LIVE?`<section class="card" style="flex-direction:row;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap"><span>${LIVE.err?`<b style="color:var(--orangeT)">${esc(LIVE.err)}</b> Showing the last data read.`:`Live from the billing sites (billing and The Moto Lab): a new bill or change shows here within seconds${LIVE.at?` · last read ${esc(LIVE.at.slice(11))}`:''}.`} Bills, job cards and customers are made and changed there.</span></section>`:'';
const capRows=list=>list.slice(0,ROWS);
const moreRows=list=>list.length>ROWS?`<small class="muted">Showing ${ROWS} of ${list.length}. Search to find the others.</small>`:'';
const invNote=()=>INV_LINK?`<section class="card" style="flex-direction:row;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap"><span>Stock comes from the Inventory portal. Add parts, stock in, transfers and stock changes are done there.</span>${/^https:\/\//.test(INV_LINK)?`<a class="btn pri" href="${esc(INV_LINK)}" target="_blank" rel="noopener">${ic('box')} Open Inventory</a>`:''}</section>`:'';
const save=()=>{const ch={},js={};for(const k in S){const j=JSON.stringify(S[k]);if(j!==SYNCED[k]){ch[k]=S[k];js[k]=j;}}
 const names=Object.keys(ch);if(!names.length)return;
 const no=names.filter(k=>!CAN.has(k));if(no.length){for(const k of names)S[k]=JSON.parse(SYNCED[k]);toast(LIVE&&no.some(k=>OLD_LISTS.includes(k))?'This comes live from the billing site. Change it there.':`Your login (${ME.roleLabel}) cannot change this.`);return false;}
 for(const k of names)SYNCED[k]=js[k];pending++;
 syncQ=syncQ.then(async()=>{try{const r=await fetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({changes:ch,ver:VER})});
   const d=await r.json().catch(()=>({}));if(r.status===401){location.reload();return;}
   if(!r.ok){toast(r.status===409?(d.error||'Someone else changed this')+' The page now shows the latest. Please do it again.':(d.error||'Could not save.'));await reloadState();return;}
   VER=d.ver;REV=d.rev;}catch(e){names.forEach(k=>delete SYNCED[k]);RETRY=true;toast('No connection. The change is kept on this page and sent again in a few seconds. Keep this page open.');}
  finally{pending--;}});};
const api=(url,body)=>fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not do that.');return d;});
setInterval(async()=>{if(pending)return;if(RETRY){RETRY=false;save();return;}if(OV||document.hidden)return;try{const d=await (await fetch('/api/rev')).json();if(d.today&&d.today!==TODAY){location.reload();return;}if(d.rev!==REV)reloadState();}catch(e){}},3000);
let UI={route:'today',param:'',authed:false,biz:'all',menu:false,tab:{},q:{},draft:null};
UI.authed=true;
let OV=null;

// ---------------- money helpers
const sub=v=>v.items.reduce((a,i)=>a+i[1]*i[2],0);
const parts=v=>sub(v)*(1-(v.disc||0)/100);
const total=v=>Math.round((parts(v)+(v.lab||0)+(v.ro||0))*100)/100;
// GST: prices include GST. A bill's lines as [rate, amount]: each part at its stock-list GST % (else the business's rate), labour at 18%
const gstRate=(v,name)=>{const it=S.inventory.find(x=>x.name===name&&x.b===v.b)||S.inventory.find(x=>x.name===name);return it&&it.tax!=null?+it.tax:+((S.gst[v.b]||[18])[0]);};
const gstLines=v=>[...v.items.filter(i=>i[2]>=0).map(i=>[gstRate(v,i[0]),i[1]*i[2]*(1-(v.disc||0)/100)]),...(v.lab?[[18,v.lab]]:[])];
function gstSum(lines){const m={};for(const [r,a] of lines){const x=m[r]||(m[r]={r,gross:0,tax:0,gst:0});x.gross+=a;x.tax+=a/(1+r/100);x.gst+=a-a/(1+r/100);}const rows=Object.values(m).sort((a,b)=>a.r-b.r);return {rows,tax:sum(rows,x=>x.tax),gst:sum(rows,x=>x.gst)};}
const inBiz=x=>(UI.biz==='all'||x.b===UI.biz)&&(!UI.br||UI.br==='all'||(x.br||(x.no||x.bills||x.cat?'rnr':UI.br))===UI.br);
const inBr=v=>!UI.br||UI.br==='all'||(v.br||'rnr')===UI.br;
const todays=()=>S.invoices.filter(v=>v.date===TODAY&&inBiz(v));
// dates: bills keep 'dd-mm-yyyy'; dkey gives 'yyyy-mm-dd' to compare, dayAgo(n) the date n days before today
const dkey=d=>String(d||'').split('-').reverse().join('-');
const p2=n=>String(n).padStart(2,'0');
const dayAgo=n=>{const [d,m,y]=TODAY.split('-').map(Number);const x=new Date(y,m-1,d-n);return `${p2(x.getDate())}-${p2(x.getMonth()+1)}-${x.getFullYear()}`;};
const daySale=d=>sum(S.invoices.filter(v=>v.date===d&&v.st==='paid'&&inBiz(v)),total);
// service advisors: the ones on today's job cards when the billing site is linked, else the sample three
// a vehicle still open from an earlier day is pending, not "in today" (meeting 29 Oct, point 5)
const OLDJ=j=>!!j.old||j.st==='stale',PENDJ=()=>S.jobs.filter(j=>j.st!=='done');
const ADVS=()=>LIVE?[...new Set(S.jobs.filter(j=>!OLDJ(j)).map(j=>j.adv).filter(Boolean))]:['Sharath','Syed Shahid','Yaseen Raza'];
// stock row by part name (for cost and brand of bill lines), built again only when the stock list changes
const invByName=()=>{if(invByName.v!==S.inventory){invByName.v=S.inventory;invByName.m=new Map(S.inventory.map(x=>[x.name,x]));}return invByName.m;};
const paidToday=()=>todays().filter(v=>v.st==='paid');
const sum=(a,f)=>a.reduce((s,x)=>s+f(x),0);
const ADV_COL={Sharath:'blue','Syed Shahid':'violet','Yaseen Raza':'teal'};
const ST={paid:['Paid','green'],pending:['Pending','orange'],draft:['Draft','gray'],returned:['Returned','red']};
const JST={ongoing:['In progress','blue'],done:['Done','green'],pending:['Waiting','gray'],paused:['Paused','violet'],delayed:['Late','orange'],stale:['Never closed','red']};
const payTxt=v=>v.pay==='Credit'?'Credit':v.pay==='Split'&&v.split?`Split · cash ${inr(v.split[0])} + UPI ${inr(v.split[1])}${v.split[2]?` + card ${inr(v.split[2])}`:''}`:v.pay||'—';
function toast(t){const el=document.createElement('div');el.className='toast';el.textContent=t;document.body.appendChild(el);setTimeout(()=>el.remove(),2400);}
function go(route,param=''){UI.route=route;UI.param=param;UI.menu=false;OV=null;try{history.pushState(null,'','#'+route+(param?'-'+param:''))}catch(e){}render();window.scrollTo(0,0);}
