function invTable(list,edit=true){edit=edit&&!INV_LINK;const all=list;list=capRows(list);return table(['ID','Part','Brand · model','Stock','Rack','Selling',...(CP()?['Cost']:[]),'GST','Discounts C / W / M','Alert at','HSN','Added',''],list.map(x=>`<tr style="${x.stock<=0?'background:color-mix(in srgb,var(--red) 7%,transparent)':x.alert>0&&x.stock<=x.alert?'background:color-mix(in srgb,var(--orange) 8%,transparent)':''}"><td class="mono muted">${x.id}</td><td><div class="cell2"><b>${esc(x.name)}</b><small class="mono">${x.serial}</small></div></td><td><div class="cell2"><b style="font-weight:600">${esc(x.brand)}</b><small>${esc(x.model)}</small></div></td><td><b style="color:${x.stock<=0?'var(--redT)':x.alert>0&&x.stock<=x.alert?'var(--orangeT)':'var(--fg)'}">${x.stock}</b>${x.stock<0?' '+pill('Below zero','red'):''}</td><td>${edit?`<input class="inp mono" value="${esc(x.rack)}" data-act="rack" data-id="${x.id}" style="width:70px;padding:6px 8px">`:x.rack}</td>${R(inr(x.sp))}${CP()?R(inr(x.cp)):''}<td>${x.tax}%${GST_OK.includes(x.tax)?'':' '+pill('Not a slab','orange')}</td><td class="mono" title="${x.discBy?'Set by '+esc(x.discBy)+(x.discAt?' on '+esc(x.discAt):''):'Not set in Spares yet'}">${x.cd} / ${x.wd} / ${x.md}%</td><td>${x.alert}</td><td class="mono muted">${x.hsn}</td><td><small class="muted">${x.by}<br>${x.date}</small></td><td>${edit?`<div class="row" style="gap:6px"><button class="btn" data-act="stock" data-id="${x.id}" data-d="1" aria-label="Add one">+1</button><button class="btn" data-act="stock" data-id="${x.id}" data-d="-1" aria-label="Remove one">−1</button></div>`:''}</td></tr>`),1280,'No parts match.')+moreRows(all)+`<small class="muted">${COLS()}</small>`;}
