const PAY_DAYS=26;
function attMonth(i,seedN){const a=[0,0,1,0,2,0,1,0,0,3,0,1,0,0,2,1,0,1,1,0][(i+seedN)%20],l=(i+seedN)%7===0?1:0,h=(i*3+seedN)%9===0?1:0,late=(i+seedN*2)%5;return {a,l,h,late};}


