const stf=n=>S.staff.find(s=>s.name===n);
const MN=['January','February','March','April','May','June','July','August','September','October','November','December'];
const mIdx=m=>{const [n,y]=m.split(' ');return +y*12+MN.indexOf(n);};
const mName=i=>MN[i%12]+' '+Math.floor(i/12);
const advCutOf=(a,month)=>{const k=mIdx(month)-mIdx(monthOf(a.date));if(k<0)return 0;const emi=a.emi||a.amt;return Math.max(0,Math.min(emi,a.amt-k*emi));};
const advCut=(name,month)=>sum(S.adv.filter(a=>a.name===name),a=>advCutOf(a,month));
const advDone=a=>{const now=mIdx('October 2026')-1;let r=0;for(let i=mIdx(monthOf(a.date));i<=now;i++)r+=advCutOf(a,mName(i));return S.salPaid['October 2026']?r+advCutOf(a,'October 2026'):r;};
const advMonths=a=>{const emi=a.emi||a.amt;const n=Math.ceil(a.amt/emi);const s=mIdx(monthOf(a.date));return [mName(s),mName(s+n-1),n];};
const monthOf=d=>{const [,m,y]=d.split('-');return ['January','February','March','April','May','June','July','August','September','October','November','December'][+m-1]+' '+y;};
const SEPT_COMM={'Irfan Shaik':4840,'Bilal Sameer':3390,'Lingaraj':3810,'Varun':3460,'Dastagir':2570,'Toufiq':1420,'Samiulla':1780,'Methab':1150,'Arif':2160};
const AUG_COMM={'Irfan Shaik':4510,'Bilal Sameer':3620,'Lingaraj':3290,'Varun':3010,'Dastagir':2890,'Toufiq':1650,'Samiulla':1540,'Methab':980,'Arif':1940};
function salRow(s,i,month){const live=month==='October 2026';const m=live?{...s.oct}:(()=>{const x=attMonth(i,month==='September 2026'?3:5);return {a:x.a,l:x.l,h:x.h,late:x.late,p:PAY_DAYS-x.a-x.l-x.h*.5};})();
 const day=s.salary/PAY_DAYS;const extraLeave=Math.max(0,m.l-1);const lateCut=Math.floor(m.late/3)*.5;
 const absDays=m.a+extraLeave+m.h*.5+lateCut;const absCut=Math.round(day*absDays);
 const adv=advCut(s.name,month);
 const comm=s.role!=='Mechanic'?0:live?(()=>{const mm=S.mechs.find(x=>x.name===s.name);return mm?commOf(mm).tot:0;})():(month==='September 2026'?SEPT_COMM:AUG_COMM)[s.name]||0;
 const base=live?Math.round(s.salary*10/PAY_DAYS):s.salary;
 return {s,m,absDays,absCut,adv,comm,base,net:base-absCut+comm-adv};}
